<script setup lang="ts">
import {ref,onMounted} from 'vue';import {get} from '../api/client'
const rows=ref<any[]>([]),total=ref(0),page=ref(1),q=ref(''),error=ref(''),busy=ref(false),timeline=ref<any>(null),selected=ref('')
async function load(){busy.value=true;error.value='';try{const data=await get('/api/v1/admin/customers',{page:page.value,size:20,q:q.value});rows.value=data.items;total.value=data.total}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function details(id:string){error.value='';try{timeline.value=await get('/api/v1/admin/analytics/customer-frequency/'+id);selected.value=id}catch(e){error.value=(e as Error).message}}
onMounted(load)
</script><template><section><h1>客户用户</h1><p class="muted">运营账号可查看用户目录和活跃频次；不显示平台身份和令牌。</p><form class="panel actions" @submit.prevent="page=1;load()"><input v-model="q" placeholder="按昵称搜索" maxlength="100"/><button :disabled="busy">搜索</button></form><p class="error" role="alert">{{ error }}</p><div class="panel scroll"><table><thead><tr><th>用户编号</th><th>昵称</th><th>状态</th><th>最近登录</th><th>最近活跃</th><th>30天活跃日</th><th>平均间隔（天）</th><th>频次</th><th>操作</th></tr></thead><tbody><tr v-for="u in rows" :key="u.id"><td>{{ u.id }}</td><td>{{ u.nickname||'未设置' }}</td><td>{{ u.status }}</td><td>{{ u.lastLoginAt||'暂无' }}</td><td>{{ u.lastActiveAt||'暂无' }}</td><td>{{ u.activeDays30 }}</td><td>{{ u.averageIntervalDays==null?'暂无':Number(u.averageIntervalDays).toFixed(1) }}</td><td>{{ u.activeDays30>=15?'高频':u.activeDays30>=5?'中频':u.activeDays30>0?'低频':'未活跃' }}</td><td><button class="quiet" @click="details(u.id)">查看活跃明细</button></td></tr></tbody></table><p v-if="!rows.length">暂无匹配账号</p><div class="actions"><button :disabled="busy||page===1" @click="page--;load()">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 条</span><button :disabled="busy||page*20>=total" @click="page++;load()">下一页</button></div></div><div v-if="timeline" class="panel"><h2>用户 {{ selected }} 的近期活动</h2><button class="quiet" @click="timeline=null">收起明细</button><p v-for="d in timeline.days" :key="d.day">{{ d.day }} · {{ d.events }} 次行为</p><table><thead><tr><th>时间</th><th>行为</th><th>对象</th></tr></thead><tbody><tr v-for="(e,i) in timeline.events" :key="i"><td>{{ e.ingestedAt }}</td><td>{{ e.eventType }}</td><td>{{ e.objectId }}</td></tr></tbody></table></div></section></template>
